    from collections import Counter
    counts = [Counter() for _ in range(3)]
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value:
                counts[(c-r) % 3][value] += 1
    mapping = {}
    for residue, counter in enumerate(counts):
        if counter:
            mapping[residue] = counter.most_common(1)[0][0]
    # Expand the two-color period encoded by the diagonal clues.
    main = max(mapping, key=lambda k: counts[k].most_common(1)[0][1])
    other = next((v for k, v in mapping.items() if k != main), None)
    if other is None:
        other = next(iter({v for counter in counts for v in counter} - {mapping[main]}))
    return [[mapping.get((c-r) % 3, other) for c in range(len(row))] for r, row in enumerate(grid)]
